 static ItemStack volume(ServerPlayer p,boolean complete){var pages=new ArrayList<net.minecraft.server.network.Filterable<net.minecraft.network.chat.Component>>();var text=new LinkedHashMap<String,String>();text.put("kingdom","Shared kingdom contributions are permanent. Review actual resources before donation; the kingdom records normalized standings and persistent personal recognition.");text.put("dimensions","The Aether opens at4, Nether at5 and Twilight at6. The End is reserved for12and future Alpha content; no End resources are needed to reach6.");text.put("construction","Only authenticated blueprints authorize projects. Crosshair previews are server checked; respect claims, full footprints, reservations and living Aldric's work area.");text.put("economy","Copper1, silver10, gold100and platinum1000represent the same conserved value. Bank and mailbox transactions need native recovery; auction taxes leave circulation.");text.put("professions","At most three professions are active. Switching costs15000coins; inactive progress remains. Master rank unlocks purchase rights, never free signature equipment.");if(complete)text.put("magic","Ars Tier2and native RARE Iron scroll catalogues support the current alpha Library. Native rarity and compatibility matter; higher technologies remain future content.");text.forEach((key,value)->pages.add(net.minecraft.server.network.Filterable.passThrough(net.minecraft.network.chat.Component.literal("subject="+key+"\n"+value))));var book=new ItemStack(Items.WRITTEN_BOOK);book.set(DataComponents.WRITTEN_BOOK_CONTENT,new net.minecraft.world.item.component.WrittenBookContent(net.minecraft.server.network.Filterable.passThrough("Kingdom reference collection"),p.getGameProfile().getName(),0,pages,true));return book;}
